cpp.setup:
auto* rootLayout = new QVBoxLayout(%PARENT%);
rootLayout->setContentsMargins(0, 0, 0, 0);
auto* shell = new fluent::layout::Card(%PARENT%);
rootLayout->addWidget(shell);
auto* shellLayout = new QVBoxLayout(shell);
shellLayout->setContentsMargins(1, 1, 1, 1);
shellLayout->setSpacing(0);
auto* control = new fluent::windowing::TitleBar(shell);
auto* content = new QWidget(control);
auto* layout = new QHBoxLayout(content);
layout->setContentsMargins(10, 0, 10, 0);
layout->setSpacing(8);
auto* icon = new fluent::FontIcon(Typography::Icons::Home, content);
icon->setIconSize(14);
layout->addWidget(icon);
auto* title = new fluent::textfields::Label(QStringLiteral("Fluent Studio"), content);
title->setFluentTypography(Typography::FontRole::BodyStrong);
layout->addWidget(title);
auto* tag = new fluent::textfields::Label(QStringLiteral("Workspace"), content);
tag->setFluentTypography(Typography::FontRole::Caption);
tag->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(tag);
layout->addStretch(1);
auto* share = new fluent::basicinput::Button(QStringLiteral("Share"), content);
share->setFluentStyle(fluent::basicinput::Button::Subtle);
share->setFluentSize(fluent::basicinput::Button::Small);
share->setFixedHeight(26);
layout->addWidget(share);
control->setContentWidget(content);
shellLayout->addWidget(control);
shellLayout->addWidget(new fluent::layout::Divider(shell));
auto* body = new QWidget(shell);
auto* bodyLayout = new QVBoxLayout(body);
bodyLayout->setContentsMargins(16, 12, 16, 14);
bodyLayout->setSpacing(4);
auto* heading = new fluent::textfields::Label(QStringLiteral("Title bar safe region"), body);
heading->setFluentTypography(Typography::FontRole::BodyStrong);
bodyLayout->addWidget(heading);
auto* hint = new fluent::textfields::Label(QStringLiteral("Adjust height or leading/trailing reserved widths to clear system window controls."), body);
hint->setFluentTypography(Typography::FontRole::Caption);
hint->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
hint->setWordWrap(true);
bodyLayout->addWidget(hint);
bodyLayout->addStretch(1);
shellLayout->addWidget(body, 1);
